-- Table: remarks
DROP TABLE IF EXISTS "remarks" CASCADE;
CREATE TABLE IF NOT EXISTS "remarks" (
    "category" TEXT,
    "created_at" TIMESTAMPTZ,
    "id" INTEGER,
    "is_active" BOOLEAN,
    "remark_text" TEXT,
    "sort_order" INTEGER,
    "test_name" TEXT,
    "updated_at" TIMESTAMPTZ,
    "usage_count" INTEGER,
    PRIMARY KEY ("id")
);

ON CONFLICT DO NOTHING;
